std::list<Kernel::Point_3>::const_iterator it = points.begin();
Kernel::Point_3 centroid = *it;
for (++it; it != points.end(); ++it) {
    centroid = centroid + *it;
}
centroid = centroid / static_cast<double>(points.size());

std::vector<Kernel::Vector_3> vectors;
for (it = points.begin(); it != points.end(); ++it) {
    vectors.push_back(*it - centroid);
}

std::vector<std::vector<double>> matrix(3, std::vector<double>(vectors.size()));
for (size_t i = 0; i < vectors.size(); ++i) {
    matrix[0][i] = vectors[i].x();
    matrix[1][i] = vectors[i].y();
    matrix[2][i] = vectors[i].z();
}

std::vector<double> eigenvalues(3);
std::vector<std::vector<double>> eigenvectors(3, std::vector<double>(3));
// Compute the covariance matrix and its eigenvectors
for (size_t i = 0; i < 3; ++i) {
    for (size_t j = 0; j < 3; ++j) {
        double sum = 0.0;
        for (size_t k = 0; k < vectors.size(); ++k) {
            sum += matrix[i][k] * matrix[j][k];
        }
        sum /= static_cast<double>(vectors.size());
        // Compute the covariance matrix
        if (i == j) {
            eigenvalues[i] = sum;
        }
    }
}
// Compute the eigenvectors (assuming the covariance matrix is diagonalizable)
for (size_t i = 0; i < 3; ++i) {
    for (size_t j = 0; j < 3; ++j) {
        if (i == j) {
            eigenvectors[i][j] = 1.0;
        } else {
            eigenvectors[i][j] = 0.0;
        }
    }
}

// Sort the eigenvectors by their corresponding eigenvalues
std::vector<size_t> indices(3);
for (size_t i = 0; i < 3; ++i) {
    indices[i] = i;
}
for (size_t i = 0; i < 3; ++i) {
    for (size_t j = i + 1; j < 3; ++j) {
        if (eigenvalues[indices[i]] > eigenvalues[indices[j]]) {
            std::swap(indices[i], indices[j]);
        }
    }
}

Kernel::Vector_3 normal(eigenvectors[indices[0]][0], eigenvectors[indices[0]][1], eigenvectors[indices[0]][2]);
return Kernel::Plane_3(normal, centroid);

